11	
12	  return {
13	    turns,
14	    carried,
15	    carries: true,
16	    release: () => release(),
17	    queue: (...more) => { scripts.push(...more); },
18	    carry(args) {
19	      carried.push(args);
20	      return this.carries;
21	    },
22	    turn(turn) {
23	      turns.push(turn);
24	      const script = scripts.shift() ?? [{ type: 'text', text: 'Done.' }];
25	      let stopped = false;
26	      const gate = new Promise(resolve => { release = resolve; });
27	      const done = (async () => {
28	        turn.onEvent({ type: 'init' });
29	        for (const step of script) {
30	          await new Promise(resolve => setImmediate(resolve));
31	          if (stopped) return { ok: false, stopped: true };
32	          if (step.type === 'wait') { await gate; continue; }
33	          if (step.type === 'fail') return { ok: false, error: step.error };
